import { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, ArrowUpRight, Check, Cloud, CloudOff, FileText, ImagePlus, LayoutDashboard, LayoutTemplate, Loader2, LogOut, Pencil, Plus, Save, Settings2, Trash2, Upload, X } from "lucide-react";
import { Link, useLocation } from "wouter";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { trpc } from "@/lib/trpc";
import { ADMIN_ACTIVITY_KEY, clearAdminActivity, clearDraft, hasPostDraft, hasProjectDraft, POST_DRAFT_KEY, PROJECT_DRAFT_KEY, readAdminActivity, readDraft, writeAdminActivity, writeDraft } from "@/lib/adminDrafts";
import PageEditorView from "@/components/PageEditorView";

const emptyProject = { title: "", titleEn: "", titleAr: "", category: "Branding", categoryEn: "Branding", categoryAr: "", description: "", descriptionEn: "", descriptionAr: "", imageUrl: null as string | null, clientName: "", sourceUrl: "", sourcePlatform: "", slides: [] as Array<{ title: string; titleEn: string; titleAr: string; description: string; descriptionEn: string; descriptionAr: string; imageUrl: string; displayOrder: number }>, published: true, displayOrder: 0 };
const emptyPost = { title: "", titleEn: "", titleAr: "", slug: "", publishedAt: new Date().toISOString().slice(0, 10), summary: "", summaryEn: "", summaryAr: "", content: "", contentEn: "", contentAr: "", imageUrl: null as string | null, published: true };
const ADMIN_IDLE_TIMEOUT_MS = 4 * 60 * 60 * 1000;
const ADMIN_SESSION_WARNING_MS = 15 * 60 * 1000;
const ADMIN_SESSION_REFRESH_INTERVAL_MS = 5 * 60 * 1000;

function formatSessionTime(milliseconds: number) {
  const totalMinutes = Math.max(0, Math.ceil(milliseconds / 60000));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours > 0 ? `${hours}h ${String(minutes).padStart(2, "0")}m` : `${minutes}m`;
}

type Tab = "overview" | "projects" | "posts" | "sections" | "page-editor";

function UploadField({ value, onChange }: { value: string | null; onChange: (value: string) => void }) {
  const upload = trpc.content.uploadImage.useMutation();
  const [fileName, setFileName] = useState("");
  const handleFile = (file?: File) => {
    if (!file) return;
    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = () => {
      const encoded = String(reader.result).split(",")[1];
      upload.mutate({ filename: file.name, mimeType: file.type, base64: encoded }, { onSuccess: result => onChange(result.url) });
    };
    reader.readAsDataURL(file);
  };

  return <div className="space-y-3"><label className="flex min-h-24 cursor-pointer items-center justify-center gap-3 rounded-lg border border-dashed border-[#d9cab1] bg-[#fffaf4] p-4 text-sm text-[#9c7860] transition hover:border-[#8f1819] hover:text-[#8f1819]"><input type="file" accept="image/*" className="sr-only" onChange={event => handleFile(event.target.files?.[0])} /><Upload size={18} />{upload.isPending ? "Uploading image…" : fileName || "Upload cover image"}</label>{value ? <div className="relative h-32 overflow-hidden rounded-lg border border-[#e5e5e5]"><img src={value} alt="Selected cover" className="h-full w-full object-cover" /><button type="button" aria-label="Remove image" onClick={() => onChange("")} className="absolute right-2 top-2 rounded-full bg-[#2d2d2d]/75 p-1 text-white"><X size={14} /></button></div> : null}</div>;
}

function UploadResumeField({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const upload = trpc.content.uploadResume.useMutation();
  const [fileName, setFileName] = useState("");
  const handleFile = (file?: File) => {
    if (!file || file.type !== "application/pdf") return;
    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = () => {
      const encoded = String(reader.result).split(",")[1];
      upload.mutate({ filename: file.name, mimeType: "application/pdf", base64: encoded }, { onSuccess: result => onChange(result.url) });
    };
    reader.readAsDataURL(file);
  };
  return <div className="space-y-3"><label className="flex min-h-24 cursor-pointer items-center justify-center gap-3 rounded-lg border border-dashed border-[#d9cab1] bg-[#fffaf4] p-4 text-sm text-[#9c7860] transition hover:border-[#8f1819] hover:text-[#8f1819]"><input type="file" accept="application/pdf,.pdf" className="sr-only" onChange={event => handleFile(event.target.files?.[0])} /><Upload size={18} />{upload.isPending ? "Uploading PDF…" : fileName || "Upload resume PDF"}</label>{value ? <div className="flex items-center justify-between gap-3 rounded-lg border border-[#e5e5e5] bg-[#fffaf4] px-3 py-3 text-sm"><a href={value} target="_blank" rel="noreferrer" className="truncate font-medium text-[#8f1819] hover:underline">Open current resume PDF</a><button type="button" aria-label="Remove resume" onClick={() => onChange("")} className="rounded-full bg-[#2d2d2d]/75 p-1 text-white"><X size={14} /></button></div> : null}</div>;
}

function BilingualFields({ label, enValue, arValue, onEnChange, onArChange, placeholder, multiline = false, required = false }: { label: string; enValue: string; arValue: string; onEnChange: (value: string) => void; onArChange: (value: string) => void; placeholder?: string; multiline?: boolean; required?: boolean }) {
  const Control = multiline ? Textarea : Input;
  return <div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1.5 text-sm"><span className="block font-medium text-[#8f1819]">{label} — English</span><Control required={required} value={enValue || ""} onChange={event => onEnChange(event.target.value)} placeholder={placeholder} dir="ltr" /></label><label className="space-y-1.5 text-right text-sm" dir="rtl"><span className="block font-medium text-[#8f1819]">{label} — العربية</span><Control required={required} value={arValue || ""} onChange={event => onArChange(event.target.value)} placeholder="أدخل النص العربي" dir="rtl" /></label></div>;
}

function AdminPage() {
  const [tab, setTab] = useState<Tab>(() => { const value = new URLSearchParams(window.location.search).get("tab") as Tab | null; return value && ["overview", "projects", "posts", "sections", "page-editor"].includes(value) ? value : "overview"; });
  const [location, setLocation] = useLocation();
  const navigateTab = (value: Tab) => { setTab(value); setLocation(value === "overview" ? "/Emadalddine" : `/Emadalddine?tab=${value}`); };
  const [projectForm, setProjectForm] = useState<any>(emptyProject);
  const [postForm, setPostForm] = useState<any>(emptyPost);
  const [editingProjectId, setEditingProjectId] = useState<number | null>(null);
  const [editingPostId, setEditingPostId] = useState<number | null>(null);
  const [notice, setNotice] = useState("");
  const [sessionRemaining, setSessionRemaining] = useState(ADMIN_IDLE_TIMEOUT_MS);
  const [sessionWarningVisible, setSessionWarningVisible] = useState(false);
  const [isOnline, setIsOnline] = useState(() => navigator.onLine);
  const [lastDraftSavedAt, setLastDraftSavedAt] = useState<number | null>(null);
  const [recoveredDraftLabel, setRecoveredDraftLabel] = useState<string | null>(null);
  const lastActivityRef = useRef(Date.now());
  const endingSessionRef = useRef(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [passwordUnlocked, setPasswordUnlocked] = useState(false);
  const utils = trpc.useUtils();
  const verifyCredentials = trpc.auth.verifyAdminCredentials.useMutation({ onSuccess: () => { setUsername(""); setPassword(""); setPasswordUnlocked(true); lastActivityRef.current = Date.now(); writeAdminActivity(lastActivityRef.current); setSessionRemaining(ADMIN_IDLE_TIMEOUT_MS); } });
  const refreshAdminSession = trpc.auth.refreshAdminSession.useMutation();
  const logoutAdmin = trpc.auth.logout.useMutation();
  const passwordStatus = trpc.auth.adminPasswordStatus.useQuery();
  const adminQuery = trpc.content.adminData.useQuery(undefined, { retry: false, enabled: passwordUnlocked });
  const saveSection = trpc.content.saveSection.useMutation({ onSuccess: () => { setNotice("Section saved and published."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const createProject = trpc.content.createProject.useMutation({ onSuccess: () => { clearDraft(PROJECT_DRAFT_KEY); setRecoveredDraftLabel(null); setProjectForm(emptyProject); setEditingProjectId(null); setNotice("Project saved."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const updateProject = trpc.content.updateProject.useMutation({ onSuccess: () => { clearDraft(PROJECT_DRAFT_KEY); setRecoveredDraftLabel(null); setProjectForm(emptyProject); setEditingProjectId(null); setNotice("Project updated."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const deleteProject = trpc.content.deleteProject.useMutation({ onSuccess: () => { setNotice("Project deleted."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const createPost = trpc.content.createPost.useMutation({ onSuccess: () => { clearDraft(POST_DRAFT_KEY); setRecoveredDraftLabel(null); setPostForm(emptyPost); setEditingPostId(null); setNotice("Post saved."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const updatePost = trpc.content.updatePost.useMutation({ onSuccess: () => { clearDraft(POST_DRAFT_KEY); setRecoveredDraftLabel(null); setPostForm(emptyPost); setEditingPostId(null); setNotice("Post updated."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });
  const deletePost = trpc.content.deletePost.useMutation({ onSuccess: () => { setNotice("Post deleted."); void utils.content.adminData.invalidate(); void utils.content.publicHome.invalidate(); } });

  const endAdminSession = () => {
    if (endingSessionRef.current) return;
    endingSessionRef.current = true;
    clearAdminActivity();
    setPasswordUnlocked(false);
    setSessionWarningVisible(false);
    setSessionRemaining(0);
    logoutAdmin.mutate(undefined, { onSettled: () => { endingSessionRef.current = false; setNotice("You have been signed out safely."); } });
  };
  const markActivity = () => { lastActivityRef.current = Date.now(); writeAdminActivity(lastActivityRef.current); setSessionRemaining(ADMIN_IDLE_TIMEOUT_MS); setSessionWarningVisible(false); };

  useEffect(() => {
    if (!passwordStatus.data?.authenticated) return;
    const lastActivity = readAdminActivity();
    if (Date.now() - lastActivity >= ADMIN_IDLE_TIMEOUT_MS) { endAdminSession(); return; }
    setPasswordUnlocked(true);
    lastActivityRef.current = lastActivity;
    setSessionRemaining(Math.max(0, ADMIN_IDLE_TIMEOUT_MS - (Date.now() - lastActivity)));
  }, [passwordStatus.data?.authenticated]);
  useEffect(() => { const value = new URLSearchParams(window.location.search).get("tab") as Tab | null; const next = value && ["overview", "projects", "posts", "sections", "page-editor"].includes(value) ? value : "overview"; setTab(next); }, [location]);
  useEffect(() => { if (notice) { const timer = window.setTimeout(() => setNotice(""), 3000); return () => window.clearTimeout(timer); } }, [notice]);
  useEffect(() => {
    const handleOnline = () => { setIsOnline(true); setNotice("Connection restored. Your local draft is still available."); };
    const handleOffline = () => { setIsOnline(false); setNotice("Offline mode: your work is being saved locally as a draft."); };
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => { window.removeEventListener("online", handleOnline); window.removeEventListener("offline", handleOffline); };
  }, []);
  useEffect(() => {
    if (!passwordUnlocked) return;
    const activityEvents = ["pointerdown", "keydown", "wheel", "touchstart"] as const;
    activityEvents.forEach(eventName => window.addEventListener(eventName, markActivity, { passive: true }));
    const countdown = window.setInterval(() => {
      const remaining = Math.max(0, ADMIN_IDLE_TIMEOUT_MS - (Date.now() - lastActivityRef.current));
      setSessionRemaining(remaining);
      if (remaining <= 0) endAdminSession();
      else if (remaining <= ADMIN_SESSION_WARNING_MS) setSessionWarningVisible(true);
    }, 1000);
    const refresh = window.setInterval(() => {
      if (Date.now() - lastActivityRef.current < ADMIN_IDLE_TIMEOUT_MS && isOnline) refreshAdminSession.mutate();
    }, ADMIN_SESSION_REFRESH_INTERVAL_MS);
    return () => { activityEvents.forEach(eventName => window.removeEventListener(eventName, markActivity)); window.clearInterval(countdown); window.clearInterval(refresh); };
  }, [passwordUnlocked, isOnline]);
  useEffect(() => {
    if (!passwordUnlocked) return;
    const projectDraft = readDraft<any>(PROJECT_DRAFT_KEY);
    const postDraft = readDraft<any>(POST_DRAFT_KEY);
    if (projectDraft && hasProjectDraft(projectDraft.value)) { setProjectForm(projectDraft.value); setEditingProjectId(projectDraft.editingId); setRecoveredDraftLabel("project"); setNotice(`Recovered your project draft from ${new Date(projectDraft.savedAt).toLocaleTimeString()}.`); }
    if (postDraft && hasPostDraft(postDraft.value)) { setPostForm(postDraft.value); setEditingPostId(postDraft.editingId); setRecoveredDraftLabel("post"); setNotice(`Recovered your post draft from ${new Date(postDraft.savedAt).toLocaleTimeString()}.`); }
  }, [passwordUnlocked]);
  useEffect(() => {
    if (!passwordUnlocked) return;
    const timer = window.setTimeout(() => {
      if (hasProjectDraft(projectForm)) { if (writeDraft(PROJECT_DRAFT_KEY, projectForm, editingProjectId)) setLastDraftSavedAt(Date.now()); }
      else clearDraft(PROJECT_DRAFT_KEY);
    }, 350);
    return () => window.clearTimeout(timer);
  }, [passwordUnlocked, projectForm, editingProjectId]);
  useEffect(() => {
    if (!passwordUnlocked) return;
    const timer = window.setTimeout(() => {
      if (hasPostDraft(postForm)) { if (writeDraft(POST_DRAFT_KEY, postForm, editingPostId)) setLastDraftSavedAt(Date.now()); }
      else clearDraft(POST_DRAFT_KEY);
    }, 350);
    return () => window.clearTimeout(timer);
  }, [passwordUnlocked, postForm, editingPostId]);
  useEffect(() => {
    if (!passwordUnlocked) return;
    const persistDrafts = () => {
      if (hasProjectDraft(projectForm)) writeDraft(PROJECT_DRAFT_KEY, projectForm, editingProjectId);
      if (hasPostDraft(postForm)) writeDraft(POST_DRAFT_KEY, postForm, editingPostId);
    };
    const handleVisibility = () => { if (document.hidden) persistDrafts(); };
    window.addEventListener("beforeunload", persistDrafts);
    window.addEventListener("pagehide", persistDrafts);
    document.addEventListener("visibilitychange", handleVisibility);
    return () => { window.removeEventListener("beforeunload", persistDrafts); window.removeEventListener("pagehide", persistDrafts); document.removeEventListener("visibilitychange", handleVisibility); };
  }, [passwordUnlocked, projectForm, editingProjectId, postForm, editingPostId]);

  const submitCredentials = (event: React.FormEvent) => { event.preventDefault(); verifyCredentials.mutate({ username, password }); };
  const data = adminQuery.data;
  const sections = data?.sections ?? [];
  const projects = data?.projects ?? [];
  const posts = data?.posts ?? [];
  const counts = useMemo(() => ({ projects: projects.length, posts: posts.length, published: projects.filter(item => item.published === 1).length + posts.filter(item => item.published === 1).length }), [projects, posts]);

  const submitProject = (event: React.FormEvent) => { event.preventDefault(); const input = { ...projectForm, title: projectForm.titleEn || projectForm.titleAr, titleEn: projectForm.titleEn || projectForm.titleAr, titleAr: projectForm.titleAr || null, category: projectForm.categoryEn || projectForm.categoryAr, categoryEn: projectForm.categoryEn || projectForm.categoryAr, categoryAr: projectForm.categoryAr || null, description: projectForm.descriptionEn || projectForm.descriptionAr, descriptionEn: projectForm.descriptionEn || projectForm.descriptionAr, descriptionAr: projectForm.descriptionAr || null, clientName: projectForm.clientName || null, sourceUrl: projectForm.sourceUrl || null, sourcePlatform: projectForm.sourcePlatform || null, imageUrl: projectForm.imageUrl || null, slides: (projectForm.slides || []).map((slide: any, index: number) => ({ ...slide, title: slide.titleEn || slide.titleAr, titleEn: slide.titleEn || slide.titleAr, titleAr: slide.titleAr || null, description: slide.descriptionEn || slide.descriptionAr || null, descriptionEn: slide.descriptionEn || slide.descriptionAr || null, descriptionAr: slide.descriptionAr || null, displayOrder: index })), displayOrder: Number(projectForm.displayOrder) || 0 }; if (editingProjectId) updateProject.mutate({ ...input, id: editingProjectId }); else createProject.mutate(input); };
  const submitPost = (event: React.FormEvent) => { event.preventDefault(); const input = { ...postForm, title: postForm.titleEn || postForm.titleAr, titleEn: postForm.titleEn || postForm.titleAr, titleAr: postForm.titleAr || null, summary: postForm.summaryEn || postForm.summaryAr, summaryEn: postForm.summaryEn || postForm.summaryAr, summaryAr: postForm.summaryAr || null, content: postForm.contentEn || postForm.contentAr, contentEn: postForm.contentEn || postForm.contentAr, contentAr: postForm.contentAr || null, imageUrl: postForm.imageUrl || null }; if (editingPostId) updatePost.mutate({ ...input, id: editingPostId }); else createPost.mutate(input); };
  const editProject = (project: any) => { setEditingProjectId(project.id); setProjectForm({ title: project.titleEn || project.title, titleEn: project.titleEn || project.title, titleAr: project.titleAr || "", category: project.categoryEn || project.category, categoryEn: project.categoryEn || project.category, categoryAr: project.categoryAr || "", description: project.descriptionEn || project.description, descriptionEn: project.descriptionEn || project.description, descriptionAr: project.descriptionAr || "", imageUrl: project.imageUrl, clientName: project.clientName || "", sourceUrl: project.sourceUrl || "", sourcePlatform: project.sourcePlatform || "", slides: (project.slides || []).map((slide: any) => ({ title: slide.titleEn || slide.title, titleEn: slide.titleEn || slide.title, titleAr: slide.titleAr || "", description: slide.descriptionEn || slide.description || "", descriptionEn: slide.descriptionEn || slide.description || "", descriptionAr: slide.descriptionAr || "", imageUrl: slide.imageUrl, displayOrder: slide.displayOrder })), published: project.published === 1, displayOrder: project.displayOrder }); navigateTab("projects"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const editPost = (post: any) => { setEditingPostId(post.id); setPostForm({ title: post.titleEn || post.title, titleEn: post.titleEn || post.title, titleAr: post.titleAr || "", slug: post.slug, publishedAt: new Date(post.publishedAt).toISOString().slice(0, 10), summary: post.summaryEn || post.summary, summaryEn: post.summaryEn || post.summary, summaryAr: post.summaryAr || "", content: post.contentEn || post.content, contentEn: post.contentEn || post.content, contentAr: post.contentAr || "", imageUrl: post.imageUrl, published: post.published === 1 }); navigateTab("posts"); window.scrollTo({ top: 0, behavior: "smooth" }); };

  if (!passwordUnlocked) return <PasswordGate username={username} setUsername={setUsername} password={password} setPassword={setPassword} onSubmit={submitCredentials} pending={verifyCredentials.isPending} error={verifyCredentials.error?.message} />;
  if (adminQuery.isLoading) return <div className="flex min-h-screen items-center justify-center bg-[#f8f1e7] text-[#8f1819]"><Loader2 className="animate-spin" /></div>;
  if (adminQuery.error) return <div className="flex min-h-screen items-center justify-center bg-[#f8f1e7] p-6 text-center"><div className="max-w-md"><div className="mx-auto mb-5 grid h-14 w-14 place-items-center rounded-full bg-[#8f1819] text-white"><Settings2 size={22} /></div><h1 className="text-2xl font-semibold text-[#8f1819]">Owner access required</h1><p className="mt-3 text-sm leading-7 text-[#9c7860]">Sign in with the owner account to access your private content control panel.</p><Link href="/" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-[#8f1819]">Back to website <ArrowUpRight size={16} /></Link></div></div>;

  return <div className="min-h-screen bg-[#f8f1e7] text-[#2d2d2d]">
    <div className="mb-6 flex flex-wrap items-center justify-between gap-4 border-b border-[#e5e5e5] pb-5"><div><p className="mb-1 text-[10px] font-semibold uppercase tracking-[.18em] text-[#bd7b6a]">Private workspace</p><h1 className="text-3xl font-semibold tracking-[-.05em] text-[#8f1819]">Content control</h1></div><div className="flex flex-wrap items-center justify-end gap-3"><div className={`inline-flex items-center gap-2 rounded-full px-3 py-2 text-xs ${isOnline ? "bg-[#f2fbf2] text-[#32623a]" : "bg-[#fff1ed] text-[#8f1819]"}`}>{isOnline ? <Cloud size={14} /> : <CloudOff size={14} />}{isOnline ? "Online" : "Offline — drafts are safe"}</div><div className={`inline-flex items-center gap-3 rounded-full px-3 py-2 text-xs ${sessionWarningVisible ? "bg-[#fff1ed] text-[#8f1819]" : "bg-[#f3e8dc] text-[#9c7860]"}`}><span>{sessionWarningVisible ? <AlertTriangle className="mr-1 inline" size={14} /> : null}Session: {formatSessionTime(sessionRemaining)}</span><button type="button" onClick={endAdminSession} className="inline-flex items-center gap-1 font-semibold text-[#8f1819] hover:underline"><LogOut size={14} />Sign out</button></div><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-[#8f1819]">View live site <ArrowUpRight size={15} /></Link></div></div>
    {notice ? <div className="mb-5 flex items-center gap-2 border border-[#bbd9be] bg-[#f2fbf2] px-4 py-3 text-sm text-[#32623a]"><Check size={16} />{notice}</div> : null}
    <div className="mb-6 flex flex-wrap gap-2 rounded-xl bg-[#fffaf4] p-2 shadow-[0_10px_35px_rgba(80,45,20,.05)]">{([['overview', 'Overview', LayoutDashboard], ['projects', 'Projects', ImagePlus], ['posts', 'Posts', FileText], ['sections', 'Site sections', Settings2], ['page-editor', 'Page Editor', LayoutTemplate]] as const).map(([value, label, Icon]) => <button key={value} onClick={() => navigateTab(value)} className={`inline-flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm transition ${tab === value ? "bg-[#8f1819] text-white" : "text-[#9c7860] hover:bg-[#f3e8dc]"}`}><Icon size={16} />{label}</button>)}</div>

    {tab === "overview" ? <Overview counts={counts} projects={projects} posts={posts} setTab={navigateTab} /> : null}
    {tab === "projects" ? <div className="grid gap-6 xl:grid-cols-[minmax(0,420px)_1fr]"><Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="flex items-center justify-between text-[#8f1819]">{editingProjectId ? "Edit project" : "New project"}{editingProjectId ? <button type="button" onClick={() => { clearDraft(PROJECT_DRAFT_KEY); setRecoveredDraftLabel(null); setEditingProjectId(null); setProjectForm(emptyProject); }} className="text-[#9c7860]"><X size={17} /></button> : null}</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={submitProject}><BilingualFields label="Title" enValue={projectForm.titleEn} arValue={projectForm.titleAr} onEnChange={(value: string) => setProjectForm({ ...projectForm, titleEn: value })} onArChange={(value: string) => setProjectForm({ ...projectForm, titleAr: value })} placeholder="Corporate Branding" required /><div className="grid gap-4 sm:grid-cols-2"><BilingualFields label="Category" enValue={projectForm.categoryEn} arValue={projectForm.categoryAr} onEnChange={(value: string) => setProjectForm({ ...projectForm, categoryEn: value })} onArChange={(value: string) => setProjectForm({ ...projectForm, categoryAr: value })} placeholder="Branding" required /><Field label="Order"><Input type="number" min="0" value={projectForm.displayOrder} onChange={event => setProjectForm({ ...projectForm, displayOrder: event.target.value })} /></Field></div><BilingualFields label="Description" enValue={projectForm.descriptionEn} arValue={projectForm.descriptionAr} onEnChange={(value: string) => setProjectForm({ ...projectForm, descriptionEn: value })} onArChange={(value: string) => setProjectForm({ ...projectForm, descriptionAr: value })} placeholder="Describe the project…" multiline required /><Field label="Client (optional)"><Input value={projectForm.clientName} onChange={event => setProjectForm({ ...projectForm, clientName: event.target.value })} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Source URL (optional)"><Input value={projectForm.sourceUrl} onChange={event => setProjectForm({ ...projectForm, sourceUrl: event.target.value })} placeholder="Behance gallery URL" /></Field><Field label="Source platform"><Input value={projectForm.sourcePlatform} onChange={event => setProjectForm({ ...projectForm, sourcePlatform: event.target.value })} placeholder="Behance" /></Field></div><Field label="Cover image (shown on Portfolio and project page)"><UploadField value={projectForm.imageUrl} onChange={value => setProjectForm({ ...projectForm, imageUrl: value })} /></Field><div className="space-y-3 rounded-lg bg-[#f8f1e7] p-3"><div className="flex items-center justify-between"><div><p className="text-sm font-medium">Project slides</p><p className="text-xs text-[#9c7860]">Add explanations, applications, mockups, and stages.</p></div><button type="button" className="inline-flex items-center gap-1 text-xs font-semibold text-[#8f1819]" onClick={() => setProjectForm({ ...projectForm, slides: [...(projectForm.slides || []), { title: "", titleEn: "", titleAr: "", description: "", descriptionEn: "", descriptionAr: "", imageUrl: "", displayOrder: (projectForm.slides || []).length }] })}><Plus size={14} />Add slide</button></div>{(projectForm.slides || []).map((slide: any, index: number) => <div key={`${index}-${slide.imageUrl}`} className="space-y-2 rounded-md border border-[#e5e5e5] bg-[#fffaf4] p-3"><div className="flex items-center justify-between"><span className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#bd7b6a]">Slide {String(index + 1).padStart(2, "0")}</span><button type="button" aria-label={`Remove slide ${index + 1}`} className="text-[#9c7860]" onClick={() => setProjectForm({ ...projectForm, slides: projectForm.slides.filter((_: any, slideIndex: number) => slideIndex !== index) })}><Trash2 size={14} /></button></div><BilingualFields label="Stage title" enValue={slide.titleEn || slide.title} arValue={slide.titleAr || ""} onEnChange={(value: string) => setProjectForm({ ...projectForm, slides: projectForm.slides.map((item: any, slideIndex: number) => slideIndex === index ? { ...item, titleEn: value } : item) })} onArChange={(value: string) => setProjectForm({ ...projectForm, slides: projectForm.slides.map((item: any, slideIndex: number) => slideIndex === index ? { ...item, titleAr: value } : item) })} placeholder="Slide title" required /><BilingualFields label="Stage description" enValue={slide.descriptionEn || slide.description || ""} arValue={slide.descriptionAr || ""} onEnChange={(value: string) => setProjectForm({ ...projectForm, slides: projectForm.slides.map((item: any, slideIndex: number) => slideIndex === index ? { ...item, descriptionEn: value } : item) })} onArChange={(value: string) => setProjectForm({ ...projectForm, slides: projectForm.slides.map((item: any, slideIndex: number) => slideIndex === index ? { ...item, descriptionAr: value } : item) })} placeholder="What does this stage show?" multiline /><Input required value={slide.imageUrl} placeholder="Uploaded image URL" onChange={event => setProjectForm({ ...projectForm, slides: projectForm.slides.map((item: any, slideIndex: number) => slideIndex === index ? { ...item, imageUrl: event.target.value } : item) })} /></div>)}</div><div className="flex items-center justify-between rounded-lg bg-[#f8f1e7] p-3"><div><p className="text-sm font-medium">Published</p><p className="text-xs text-[#9c7860]">Show this project on the public site.</p></div><Switch checked={projectForm.published} onCheckedChange={value => setProjectForm({ ...projectForm, published: value })} /></div><DraftStatus kind="project" isOnline={isOnline} savedAt={lastDraftSavedAt} recovered={recoveredDraftLabel === "project"} onClear={() => { clearDraft(PROJECT_DRAFT_KEY); setLastDraftSavedAt(null); setRecoveredDraftLabel(null); setProjectForm(emptyProject); setEditingProjectId(null); }} /><Button type="submit" disabled={createProject.isPending || updateProject.isPending} className="w-full bg-[#8f1819] text-white hover:bg-[#701314]"><Save size={16} />{editingProjectId ? "Update project" : "Save project"}</Button></form></CardContent></Card><ContentTable kind="projects" items={projects} onEdit={editProject} onDelete={id => { if (window.confirm("Delete this project?")) deleteProject.mutate({ id }); }} onToggle={project => updateProject.mutate({ id: project.id, title: project.titleEn || project.title, titleEn: project.titleEn || project.title, titleAr: project.titleAr || null, category: project.categoryEn || project.category, categoryEn: project.categoryEn || project.category, categoryAr: project.categoryAr || null, description: project.descriptionEn || project.description, descriptionEn: project.descriptionEn || project.description, descriptionAr: project.descriptionAr || null, imageUrl: project.imageUrl, clientName: project.clientName, sourceUrl: project.sourceUrl, sourcePlatform: project.sourcePlatform, slides: project.slides || [], published: project.published !== 1, displayOrder: project.displayOrder })} /></div> : null}
    {tab === "posts" ? <div className="grid gap-6 xl:grid-cols-[minmax(0,420px)_1fr]"><Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="flex items-center justify-between text-[#8f1819]">{editingPostId ? "Edit post" : "New post"}{editingPostId ? <button type="button" onClick={() => { clearDraft(POST_DRAFT_KEY); setRecoveredDraftLabel(null); setEditingPostId(null); setPostForm(emptyPost); }} className="text-[#9c7860]"><X size={17} /></button> : null}</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={submitPost}><BilingualFields label="Title" enValue={postForm.titleEn} arValue={postForm.titleAr} onEnChange={(value: string) => setPostForm({ ...postForm, titleEn: value })} onArChange={(value: string) => setPostForm({ ...postForm, titleAr: value })} placeholder="A thoughtful update" required /><Field label="Slug"><Input required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value={postForm.slug} onChange={event => setPostForm({ ...postForm, slug: event.target.value })} placeholder="a-thoughtful-update" /></Field><Field label="Publish date"><Input required type="date" value={postForm.publishedAt} onChange={event => setPostForm({ ...postForm, publishedAt: event.target.value })} /></Field><BilingualFields label="Summary" enValue={postForm.summaryEn} arValue={postForm.summaryAr} onEnChange={(value: string) => setPostForm({ ...postForm, summaryEn: value })} onArChange={(value: string) => setPostForm({ ...postForm, summaryAr: value })} placeholder="A short summary for the post card…" multiline required /><BilingualFields label="Body" enValue={postForm.contentEn} arValue={postForm.contentAr} onEnChange={(value: string) => setPostForm({ ...postForm, contentEn: value })} onArChange={(value: string) => setPostForm({ ...postForm, contentAr: value })} placeholder="Write the full post content…" multiline required /><Field label="Cover image (shown on the post card and detail page)"><UploadField value={postForm.imageUrl} onChange={value => setPostForm({ ...postForm, imageUrl: value })} /></Field><div className="flex items-center justify-between rounded-lg bg-[#f8f1e7] p-3"><div><p className="text-sm font-medium">Published</p><p className="text-xs text-[#9c7860]">Show this post on the public site.</p></div><Switch checked={postForm.published} onCheckedChange={value => setPostForm({ ...postForm, published: value })} /></div><DraftStatus kind="post" isOnline={isOnline} savedAt={lastDraftSavedAt} recovered={recoveredDraftLabel === "post"} onClear={() => { clearDraft(POST_DRAFT_KEY); setLastDraftSavedAt(null); setRecoveredDraftLabel(null); setPostForm(emptyPost); setEditingPostId(null); }} /><Button type="submit" disabled={createPost.isPending || updatePost.isPending} className="w-full bg-[#8f1819] text-white hover:bg-[#701314]"><Save size={16} />{editingPostId ? "Update post" : "Save post"}</Button></form></CardContent></Card><ContentTable kind="posts" items={posts} onEdit={editPost} onDelete={id => { if (window.confirm("Delete this post?")) deletePost.mutate({ id }); }} onToggle={post => updatePost.mutate({ id: post.id, title: post.titleEn || post.title, titleEn: post.titleEn || post.title, titleAr: post.titleAr || null, slug: post.slug, publishedAt: post.publishedAt, summary: post.summaryEn || post.summary, summaryEn: post.summaryEn || post.summary, summaryAr: post.summaryAr || null, content: post.contentEn || post.content, contentEn: post.contentEn || post.content, contentAr: post.contentAr || null, imageUrl: post.imageUrl, published: post.published !== 1 })} /></div> : null}
    {tab === "sections" ? <SectionsEditor sections={sections} onSave={(input) => saveSection.mutate(input)} saving={saveSection.isPending} /> : null}
    {tab === "page-editor" ? <PageEditorView sections={sections} onSave={(input) => saveSection.mutate(input)} saving={saveSection.isPending} /> : null}
  </div>;
}

function PasswordGate({ username, setUsername, password, setPassword, onSubmit, pending, error }: { username: string; setUsername: (value: string) => void; password: string; setPassword: (value: string) => void; onSubmit: (event: React.FormEvent) => void; pending: boolean; error?: string }) { return <div className="admin-login-page"><Card className="admin-login-card"><CardHeader className="text-center"><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-full bg-[#8f1819] text-white"><Settings2 size={20} /></div><CardTitle className="text-2xl text-[#8f1819]">Emadalddine</CardTitle><p className="text-sm leading-6 text-[#9c7860]">Private content control panel</p></CardHeader><CardContent><form className="space-y-4" onSubmit={onSubmit}><Field label="Username"><Input autoFocus required value={username} onChange={event => setUsername(event.target.value)} placeholder="Emadalddine" autoComplete="username" /></Field><Field label="Password"><Input required type="password" value={password} onChange={event => setPassword(event.target.value)} placeholder="Enter your password" autoComplete="current-password" /></Field>{error ? <p className="text-sm text-[#8f1819]">{error}</p> : null}<Button type="submit" disabled={pending} className="w-full bg-[#8f1819] text-white hover:bg-[#701314]">{pending ? <Loader2 className="animate-spin" size={16} /> : <Settings2 size={16} />}Sign in</Button></form><div className="admin-recovery"><span>Forgot your password?</span><a href="mailto:Emad.i202020@gmail.com?subject=Emadalddine%20control%20panel%20password%20reset">Email recovery</a><a href="https://wa.me/966504487308?text=I%20need%20help%20resetting%20my%20Emadalddine%20password" target="_blank" rel="noreferrer">WhatsApp recovery</a></div></CardContent></Card></div>; }

function Overview({ counts, projects, posts, setTab }: { counts: { projects: number; posts: number; published: number }; projects: any[]; posts: any[]; setTab: (tab: Tab) => void }) {
  return <div className="space-y-6"><div className="grid gap-4 md:grid-cols-3">{[['Projects', counts.projects, ImagePlus], ['Posts', counts.posts, FileText], ['Published items', counts.published, Check]].map(([label, value, Icon]: any) => <Card key={label} className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardContent className="flex items-center justify-between p-6"><div><p className="text-xs uppercase tracking-[.15em] text-[#bd7b6a]">{label}</p><strong className="mt-2 block text-4xl font-semibold tracking-[-.06em] text-[#8f1819]">{value}</strong></div><div className="grid h-11 w-11 place-items-center rounded-full bg-[#f3e8dc] text-[#8f1819]"><Icon size={20} /></div></CardContent></Card>)}</div><div className="grid gap-6 lg:grid-cols-2"><Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="text-[#8f1819]">Recent projects</CardTitle></CardHeader><CardContent className="space-y-3">{projects.slice(0, 4).map(project => <div className="flex items-center justify-between gap-4 border-b border-[#eee4d6] pb-3" key={project.id}><div><p className="font-medium">{project.title}</p><p className="text-xs text-[#9c7860]">{project.category}</p></div><Badge className={project.published ? "bg-[#e6f4e7] text-[#32623a]" : "bg-[#f3e8dc] text-[#9c7860]"}>{project.published ? "Published" : "Draft"}</Badge></div>)}{projects.length === 0 ? <Empty text="No projects yet." action="Add project" onClick={() => setTab("projects")} /> : null}</CardContent></Card><Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="text-[#8f1819]">Recent posts</CardTitle></CardHeader><CardContent className="space-y-3">{posts.slice(0, 4).map(post => <div className="flex items-center justify-between gap-4 border-b border-[#eee4d6] pb-3" key={post.id}><div><p className="font-medium">{post.title}</p><p className="text-xs text-[#9c7860]">{new Date(post.publishedAt).toLocaleDateString()}</p></div><Badge className={post.published ? "bg-[#e6f4e7] text-[#32623a]" : "bg-[#f3e8dc] text-[#9c7860]"}>{post.published ? "Published" : "Draft"}</Badge></div>)}{posts.length === 0 ? <Empty text="No posts yet." action="Add post" onClick={() => setTab("posts")} /> : null}</CardContent></Card></div></div>;
}

function ContentTable({ kind, items, onEdit, onDelete, onToggle }: { kind: "projects" | "posts"; items: any[]; onEdit: (item: any) => void; onDelete: (id: number) => void; onToggle: (item: any) => void }) {
  return <Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="text-[#8f1819]">Your {kind}</CardTitle></CardHeader><CardContent>{items.length === 0 ? <Empty text={`No ${kind} created yet.`} /> : <div className="space-y-3">{items.map(item => <div key={item.id} className="flex flex-wrap items-center gap-3 rounded-lg border border-[#eee4d6] p-3"><div className="h-14 w-16 shrink-0 overflow-hidden rounded bg-[#f3e8dc]">{item.imageUrl ? <img src={item.imageUrl} alt="" className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center text-[#bd7b6a]"><ImagePlus size={17} /></div>}</div><div className="min-w-0 flex-1"><p className="truncate font-medium">{item.title}</p><p className="truncate text-xs text-[#9c7860]">{kind === "projects" ? item.category : item.slug}</p></div><Badge className={item.published ? "bg-[#e6f4e7] text-[#32623a]" : "bg-[#f3e8dc] text-[#9c7860]"}>{item.published ? "Published" : "Draft"}</Badge><div className="flex items-center gap-1"><Button variant="ghost" size="icon" onClick={() => onToggle(item)} aria-label="Toggle publish"><Check size={16} /></Button><Button variant="ghost" size="icon" onClick={() => onEdit(item)} aria-label="Edit"><Pencil size={16} /></Button><Button variant="ghost" size="icon" onClick={() => onDelete(item.id)} aria-label="Delete" className="text-[#8f1819]"><Trash2 size={16} /></Button></div></div>)}</div>}</CardContent></Card>;
}

function DraftStatus({ kind, isOnline, savedAt, recovered, onClear }: { kind: "project" | "post"; isOnline: boolean; savedAt: number | null; recovered: boolean; onClear: () => void }) {
  return <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-[#e5e5e5] bg-[#fffaf4] px-3 py-2.5 text-xs text-[#9c7860]"><span className="inline-flex items-center gap-2">{isOnline ? <Cloud size={14} className="text-[#32623a]" /> : <CloudOff size={14} className="text-[#8f1819]" />}{recovered ? `${kind === "project" ? "Project" : "Post"} draft recovered. ` : "Draft saves locally as you type. "}{savedAt ? `Last saved ${new Date(savedAt).toLocaleTimeString()}.` : ""}</span>{(savedAt || recovered) ? <button type="button" onClick={onClear} className="font-semibold text-[#8f1819] hover:underline">Discard draft</button> : null}</div>;
}

