const defaultServicesCopy = { eyebrow: "My Services", eyebrowEn: "My Services", eyebrowAr: "خدماتي", title: "Professional design", titleEn: "Professional design", titleAr: "حلول تصميم", accent: "solutions", accentEn: "solutions", accentAr: "احترافية", intro: "Professional design solutions tailored to your needs", introEn: "Professional design solutions tailored to your needs", introAr: "حلول تصميم احترافية مصممة لتناسب احتياجاتك", popular: "Most Popular", popularEn: "Most Popular", popularAr: "الأكثر طلباً", startingAt: "Starting at", startingAtEn: "Starting at", startingAtAr: "تبدأ من", currency: "SAR", currencyAr: "ريال", getStarted: "Get Started", getStartedEn: "Get Started", getStartedAr: "ابدأ الآن", processEyebrow: "My Design Process", processEyebrowEn: "My Design Process", processEyebrowAr: "منهجية التصميم", processTitle: "A streamlined process", processTitleEn: "A streamlined process", processTitleAr: "منهجية واضحة", processAccent: "from brief to delivery.", processAccentEn: "from brief to delivery.", processAccentAr: "من الموجز حتى التسليم.", processDescription: "A streamlined process to ensure your project is delivered on time and exceeds expectations", processDescriptionEn: "A streamlined process to ensure your project is delivered on time and exceeds expectations", processDescriptionAr: "منهجية منظمة لضمان تسليم مشروعك في الوقت المناسب وبجودة تتجاوز التوقعات.", readyTitle: "Ready to Get Started?", readyTitleEn: "Ready to Get Started?", readyTitleAr: "هل أنت مستعد للبدء؟", readyDescription: "Let's discuss your project and create something amazing together. Contact me for a free consultation.", readyDescriptionEn: "Let's discuss your project and create something amazing together. Contact me for a free consultation.", readyDescriptionAr: "لنتحدث عن مشروعك ونصنع معاً شيئاً مميزاً. تواصل معي للحصول على استشارة مجانية.", readyButton: "WhatsApp Chat", readyButtonEn: "WhatsApp Chat", readyButtonAr: "محادثة واتساب" };
