function SectionsEditor({ sections, onSave, saving }: { sections: any[]; onSave: (input: any) => void; saving: boolean }) {
  const section = (key: string) => sections.find(item => item.key === key);
  const [hero, setHero] = useState(() => ({ title: section("hero")?.title || "Creative Design Solutions", titleEn: section("hero")?.titleEn || section("hero")?.title || "Creative Design Solutions", titleAr: section("hero")?.titleAr || "", subtitle: section("hero")?.subtitle || "Transforming ideas into impactful visual experiences with 9+ years of expertise", subtitleEn: section("hero")?.subtitleEn || section("hero")?.subtitle || "Transforming ideas into impactful visual experiences with 9+ years of expertise", subtitleAr: section("hero")?.subtitleAr || "" }));
  const [about, setAbout] = useState(() => ({ content: section("about")?.content || "Creative graphic designer with 9+ years of experience in branding and visual identity development.", contentEn: section("about")?.contentEn || section("about")?.content || "Creative graphic designer with 9+ years of experience in branding and visual identity development.", contentAr: section("about")?.contentAr || "" }));
  const [contact, setContact] = useState(() => ({ title: section("contact")?.title || "info@emadalddine.com", titleEn: section("contact")?.titleEn || section("contact")?.title || "info@emadalddine.com", titleAr: section("contact")?.titleAr || "", subtitle: section("contact")?.subtitle || "+966 504487308", subtitleEn: section("contact")?.subtitleEn || section("contact")?.subtitle || "+966 504487308", subtitleAr: section("contact")?.subtitleAr || "", content: section("contact")?.content || "Al-Madina, Saudi Arabia", contentEn: section("contact")?.contentEn || section("contact")?.content || "Al-Madina, Saudi Arabia", contentAr: section("contact")?.contentAr || "" }));
  const [links, setLinks] = useState(() => { try { return JSON.parse(section("links")?.content || "{}"); } catch { return {}; } });
  const [services, setServices] = useState(() => { try { const parsed = JSON.parse(section("services")?.content || "null"); return Array.isArray(parsed) && parsed.length >= 5 ? parsed : defaultServices; } catch { return defaultServices; } });
  const [servicesCopy, setServicesCopy] = useState(() => { try { const parsed = JSON.parse(section("services_copy")?.content || "null"); return parsed && typeof parsed === "object" && "readyTitle" in parsed ? { ...defaultServicesCopy, ...parsed } : defaultServicesCopy; } catch { return defaultServicesCopy; } });
  const [processCopy, setProcessCopy] = useState(() => { try { const parsed = JSON.parse(section("services_process")?.content || "null"); return parsed && Array.isArray(parsed.steps) && parsed.steps.length >= 4 ? { ...defaultProcessCopy, ...parsed } : defaultProcessCopy; } catch { return defaultProcessCopy; } });
  const [resumeUrl, setResumeUrl] = useState(() => section("resume")?.imageUrl || "");
  const [portraitUrl, setPortraitUrl] = useState(() => section("portrait")?.imageUrl || "");
  return <div className="grid gap-6 xl:grid-cols-2"><SectionCard title="Hero" description="The first impression on the public homepage."><BilingualFields label="Headline" enValue={hero.titleEn} arValue={hero.titleAr} onEnChange={(value: string) => setHero({ ...hero, title: value, titleEn: value })} onArChange={(value: string) => setHero({ ...hero, titleAr: value })} placeholder="Creative Design Solutions" /><BilingualFields label="Supporting line" enValue={hero.subtitleEn} arValue={hero.subtitleAr} onEnChange={(value: string) => setHero({ ...hero, subtitle: value, subtitleEn: value })} onArChange={(value: string) => setHero({ ...hero, subtitleAr: value })} placeholder="Transforming ideas into impactful visual experiences" multiline /><SaveButton saving={saving} onClick={() => onSave({ key: "hero", title: hero.titleEn || hero.title, titleEn: hero.titleEn || hero.title, titleAr: hero.titleAr || null, subtitle: hero.subtitleEn || hero.subtitle, subtitleEn: hero.subtitleEn || hero.subtitle, subtitleAr: hero.subtitleAr || null })} /></SectionCard><SectionCard title="About / Bio" description="Your public profile introduction."><BilingualFields label="Bio" enValue={about.contentEn} arValue={about.contentAr} onEnChange={(value: string) => setAbout({ ...about, content: value, contentEn: value })} onArChange={(value: string) => setAbout({ ...about, contentAr: value })} placeholder="Creative graphic designer with 9+ years of experience…" multiline /><SaveButton saving={saving} onClick={() => onSave({ key: "about", content: about.contentEn || about.content, contentEn: about.contentEn || about.content, contentAr: about.contentAr || null })} /></SectionCard><SectionCard title="Contact" description="Email, phone, and location shown in the CTA and footer."><BilingualFields label="Email" enValue={contact.titleEn} arValue={contact.titleAr} onEnChange={(value: string) => setContact({ ...contact, title: value, titleEn: value })} onArChange={(value: string) => setContact({ ...contact, titleAr: value })} placeholder="info@emadalddine.com" /><BilingualFields label="Phone" enValue={contact.subtitleEn} arValue={contact.subtitleAr} onEnChange={(value: string) => setContact({ ...contact, subtitle: value, subtitleEn: value })} onArChange={(value: string) => setContact({ ...contact, subtitleAr: value })} placeholder="+966 504487308" /><BilingualFields label="Location" enValue={contact.contentEn} arValue={contact.contentAr} onEnChange={(value: string) => setContact({ ...contact, content: value, contentEn: value })} onArChange={(value: string) => setContact({ ...contact, contentAr: value })} placeholder="Al-Madina, Saudi Arabia" /><SaveButton saving={saving} onClick={() => onSave({ key: "contact", title: contact.titleEn || contact.title, titleEn: contact.titleEn || contact.title, titleAr: contact.titleAr || null, subtitle: contact.subtitleEn || contact.subtitle, subtitleEn: contact.subtitleEn || contact.subtitle, subtitleAr: contact.subtitleAr || null, content: contact.contentEn || contact.content, contentEn: contact.contentEn || contact.content, contentAr: contact.contentAr || null })} /></SectionCard><SectionCard title="Social links" description="Keep your public profiles current."><Field label="Instagram"><Input value={links.instagram || ""} onChange={event => setLinks({ ...links, instagram: event.target.value })} /></Field><Field label="LinkedIn"><Input value={links.linkedin || ""} onChange={event => setLinks({ ...links, linkedin: event.target.value })} /></Field><Field label="Behance"><Input value={links.behance || ""} onChange={event => setLinks({ ...links, behance: event.target.value })} /></Field><SaveButton saving={saving} onClick={() => onSave({ key: "links", content: JSON.stringify(links) })} /></SectionCard><SectionCard title="Services" description="Edit the three service cards shown on the Services page.">{services.map((service: any, index: number) => <div className="space-y-3 rounded-lg border border-[#eee4d6] p-4" key={service.number}><p className="text-xs font-semibold uppercase tracking-[.15em] text-[#bd7b6a]">Service {service.number}</p><BilingualFields label="Title" enValue={service.titleEn || service.title || ""} arValue={service.titleAr || ""} onEnChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, title: value, titleEn: value } : item))} onArChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, titleAr: value } : item))} /><BilingualFields label="Description" enValue={service.descriptionEn || service.description || ""} arValue={service.descriptionAr || ""} onEnChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, description: value, descriptionEn: value } : item))} onArChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, descriptionAr: value } : item))} multiline /><BilingualFields label="Details" enValue={service.detailsEn || service.details || ""} arValue={service.detailsAr || ""} onEnChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, details: value, detailsEn: value } : item))} onArChange={(value: string) => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, detailsAr: value } : item))} /><div className="grid gap-3 sm:grid-cols-2"><Field label="Starting price"><Input value={service.priceEn || service.price || ""} onChange={event => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, price: event.target.value, priceEn: event.target.value } : item))} placeholder="560" /></Field><label className="flex items-center justify-between rounded-lg bg-[#f8f1e7] px-3 py-2 text-sm"><span>Most popular</span><Switch checked={service.popular === true || service.popular === "true"} onCheckedChange={value => setServices(items => items.map((item, itemIndex) => itemIndex === index ? { ...item, popular: value } : item))} /></label></div></div>)}<SaveButton saving={saving} onClick={() => onSave({ key: "services", content: JSON.stringify(services), contentEn: JSON.stringify(services), contentAr: JSON.stringify(services) })} /></SectionCard><SectionCard title="Services page copy" description="Edit all headings, labels, prices, and CTA text shown on the Services page."><BilingualFields label="Eyebrow" enValue={servicesCopy.eyebrowEn || servicesCopy.eyebrow || ""} arValue={servicesCopy.eyebrowAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, eyebrow: value, eyebrowEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, eyebrowAr: value })} /><BilingualFields label="Main title" enValue={servicesCopy.titleEn || servicesCopy.title || ""} arValue={servicesCopy.titleAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, title: value, titleEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, titleAr: value })} /><BilingualFields label="Accent line" enValue={servicesCopy.accentEn || servicesCopy.accent || ""} arValue={servicesCopy.accentAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, accent: value, accentEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, accentAr: value })} /><BilingualFields label="Intro" enValue={servicesCopy.introEn || servicesCopy.intro || ""} arValue={servicesCopy.introAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, intro: value, introEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, introAr: value })} multiline /><BilingualFields label="Offer title" enValue={servicesCopy.offerTitleEn || servicesCopy.offerTitle || ""} arValue={servicesCopy.offerTitleAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, offerTitle: value, offerTitleEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, offerTitleAr: value })} /><BilingualFields label="Offer accent" enValue={servicesCopy.offerAccentEn || servicesCopy.offerAccent || ""} arValue={servicesCopy.offerAccentAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, offerAccent: value, offerAccentEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, offerAccentAr: value })} /><BilingualFields label="Offer description" enValue={servicesCopy.offerDescriptionEn || servicesCopy.offerDescription || ""} arValue={servicesCopy.offerDescriptionAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, offerDescription: value, offerDescriptionEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, offerDescriptionAr: value })} multiline /><div className="grid gap-3 sm:grid-cols-2"><BilingualFields label="Popular badge" enValue={servicesCopy.popularEn || servicesCopy.popular || ""} arValue={servicesCopy.popularAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, popular: value, popularEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, popularAr: value })} /><BilingualFields label="Starting at" enValue={servicesCopy.startingAtEn || servicesCopy.startingAt || ""} arValue={servicesCopy.startingAtAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, startingAt: value, startingAtEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, startingAtAr: value })} /></div><BilingualFields label="Currency" enValue={servicesCopy.currencyEn || servicesCopy.currency || ""} arValue={servicesCopy.currencyAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, currency: value, currencyEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, currencyAr: value })} /><BilingualFields label="Get started button" enValue={servicesCopy.getStartedEn || servicesCopy.getStarted || ""} arValue={servicesCopy.getStartedAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, getStarted: value, getStartedEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, getStartedAr: value })} /><BilingualFields label="Process eyebrow" enValue={servicesCopy.processEyebrowEn || servicesCopy.processEyebrow || ""} arValue={servicesCopy.processEyebrowAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, processEyebrow: value, processEyebrowEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, processEyebrowAr: value })} /><BilingualFields label="Process title" enValue={servicesCopy.processTitleEn || servicesCopy.processTitle || ""} arValue={servicesCopy.processTitleAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, processTitle: value, processTitleEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, processTitleAr: value })} /><BilingualFields label="Process accent" enValue={servicesCopy.processAccentEn || servicesCopy.processAccent || ""} arValue={servicesCopy.processAccentAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, processAccent: value, processAccentEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, processAccentAr: value })} /><BilingualFields label="Process description" enValue={servicesCopy.processDescriptionEn || servicesCopy.processDescription || ""} arValue={servicesCopy.processDescriptionAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, processDescription: value, processDescriptionEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, processDescriptionAr: value })} multiline /><BilingualFields label="Ready CTA title" enValue={servicesCopy.readyTitleEn || servicesCopy.readyTitle || ""} arValue={servicesCopy.readyTitleAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, readyTitle: value, readyTitleEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, readyTitleAr: value })} /><BilingualFields label="Ready CTA description" enValue={servicesCopy.readyDescriptionEn || servicesCopy.readyDescription || ""} arValue={servicesCopy.readyDescriptionAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, readyDescription: value, readyDescriptionEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, readyDescriptionAr: value })} multiline /><BilingualFields label="Ready CTA button" enValue={servicesCopy.readyButtonEn || servicesCopy.readyButton || ""} arValue={servicesCopy.readyButtonAr || ""} onEnChange={(value: string) => setServicesCopy({ ...servicesCopy, readyButton: value, readyButtonEn: value })} onArChange={(value: string) => setServicesCopy({ ...servicesCopy, readyButtonAr: value })} /><SaveButton saving={saving} onClick={() => onSave({ key: "services_copy", content: JSON.stringify(servicesCopy), contentEn: JSON.stringify(servicesCopy), contentAr: JSON.stringify(servicesCopy) })} /></SectionCard><SectionCard title="Process copy" description="Edit the process heading and four process steps."><BilingualFields label="Heading" enValue={processCopy.titleEn || processCopy.title || ""} arValue={processCopy.titleAr || ""} onEnChange={(value: string) => setProcessCopy({ ...processCopy, title: value, titleEn: value })} onArChange={(value: string) => setProcessCopy({ ...processCopy, titleAr: value })} /><BilingualFields label="Accent" enValue={processCopy.accentEn || processCopy.accent || ""} arValue={processCopy.accentAr || ""} onEnChange={(value: string) => setProcessCopy({ ...processCopy, accent: value, accentEn: value })} onArChange={(value: string) => setProcessCopy({ ...processCopy, accentAr: value })} /><BilingualFields label="Description" enValue={processCopy.descriptionEn || processCopy.description || ""} arValue={processCopy.descriptionAr || ""} onEnChange={(value: string) => setProcessCopy({ ...processCopy, description: value, descriptionEn: value })} onArChange={(value: string) => setProcessCopy({ ...processCopy, descriptionAr: value })} multiline />{processCopy.steps.map((step: any, index: number) => <div className="space-y-3 rounded-lg border border-[#eee4d6] p-4" key={step.number}><p className="text-xs font-semibold uppercase tracking-[.15em] text-[#bd7b6a]">Step {step.number}</p><BilingualFields label="Title" enValue={step.titleEn || step.title || ""} arValue={step.titleAr || ""} onEnChange={(value: string) => setProcessCopy({ ...processCopy, steps: processCopy.steps.map((item: any, itemIndex: number) => itemIndex === index ? { ...item, title: value, titleEn: value } : item) })} onArChange={(value: string) => setProcessCopy({ ...processCopy, steps: processCopy.steps.map((item: any, itemIndex: number) => itemIndex === index ? { ...item, titleAr: value } : item) })} /><BilingualFields label="Description" enValue={step.descriptionEn || step.description || ""} arValue={step.descriptionAr || ""} onEnChange={(value: string) => setProcessCopy({ ...processCopy, steps: processCopy.steps.map((item: any, itemIndex: number) => itemIndex === index ? { ...item, description: value, descriptionEn: value } : item) })} onArChange={(value: string) => setProcessCopy({ ...processCopy, steps: processCopy.steps.map((item: any, itemIndex: number) => itemIndex === index ? { ...item, descriptionAr: value } : item) })} multiline /></div>)}<SaveButton saving={saving} onClick={() => onSave({ key: "services_process", content: JSON.stringify(processCopy), contentEn: JSON.stringify(processCopy), contentAr: JSON.stringify(processCopy) })} /></SectionCard><SectionCard title="Profile portrait" description="Upload the portrait used across the public hero and portrait compositions."><UploadField value={portraitUrl} onChange={setPortraitUrl} /><SaveButton saving={saving} onClick={() => onSave({ key: "portrait", imageUrl: portraitUrl || null, title: "Profile portrait", titleEn: "Profile portrait", titleAr: "الصورة الشخصية" })} /></SectionCard><SectionCard title="Resume / CV" description="Upload the PDF used by the Download CV button on the public homepage."><UploadResumeField value={resumeUrl} onChange={setResumeUrl} /><SaveButton saving={saving} onClick={() => onSave({ key: "resume", imageUrl: resumeUrl || null, title: "Resume PDF", titleEn: "Resume PDF", titleAr: "السيرة الذاتية PDF" })} /></SectionCard></div>;
}

function SectionCard({ title, description, children }: { title: string; description: string; children: React.ReactNode }) { return <Card className="border-0 bg-[#fffaf4] shadow-[0_10px_35px_rgba(80,45,20,.05)]"><CardHeader><CardTitle className="text-[#8f1819]">{title}</CardTitle><p className="text-sm text-[#9c7860]">{description}</p></CardHeader><CardContent className="space-y-4">{children}</CardContent></Card>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block space-y-1.5"><span className="text-xs font-semibold text-[#9c7860]">{label}</span>{children}</label>; }
function SaveButton({ saving, onClick }: { saving: boolean; onClick: () => void }) { return <Button type="button" onClick={onClick} disabled={saving} className="bg-[#8f1819] text-white hover:bg-[#701314]"><Save size={16} />{saving ? "Saving…" : "Save section"}</Button>; }
function Empty({ text, action, onClick }: { text: string; action?: string; onClick?: () => void }) { return <div className="rounded-lg border border-dashed border-[#d9cab1] p-7 text-center text-sm text-[#9c7860]"><p>{text}</p>{action && onClick ? <Button variant="outline" className="mt-3 border-[#d9cab1] text-[#8f1819]" onClick={onClick}><Plus size={15} />{action}</Button> : null}</div>; }

export default function Admin() { return <AdminPage />; }
